pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        // Record the initial number of calls to caddress via a dummy proxy (we cannot observe internal state, so we use a balance heuristic)
        uint256 beforeBalance = address(caddress).balance;
        // Generate a unique 'v' that adds distinct wei on each call to track count
        // We'll send 1 wei per call to make call count observable
        uint256 totalValue = _tos.length * 1e9; // wei per transfer
        (bool success, ) = address(caddress).call{value: totalValue}("");
        vm.assume(success);
        // Now call target transfer
        c.transfer(from, caddress, _tos, v);
        // After transfer, the caddress balance should have increased by at least (_tos.length * 1e9) because each successful call returns value (the mutant may skip fail calls)
        // To make it general, we require that the balance increase is exactly _tos.length * 1e9 (the reference always succeeds all calls)
        uint256 afterBalance = address(caddress).balance;
        uint256 increase = afterBalance - beforeBalance - totalValue;
        // The reference contract's transfer returns true (doesn't revert) and performs all calls; the bug may revert early
        // But here we observe balance: the reference always adds value from each call, the mutant may skip if call fails
        // A simpler rule: the transfer call itself must return true (the reference always does)
        // For the reference, transfer always returns true
        // The buggy version returns true always as well (removed require), so that rule doesn't hold. Instead, we check that the number of calls (observable via a reentrant counter) matches
        // Since we cannot observe calls directly, we use a trick: deploy a helper contract that counts calls, but that would change the test.
        // Alternative: The rule that reference returns true and does not revert, bug does not revert either. So we need another rule.
        // A valid rule: the sum of balances of from, caddress, and the contract itself is conserved (no ether lost).
        uint256 sumBefore = from.balance + address(caddress).balance + address(c).balance;
        c.transfer(from, caddress, _tos, v);
        uint256 sumAfter = from.balance + address(caddress).balance + address(c).balance;
        assertTrue(sumBefore == sumAfter, "ether conserved");
    }
}

