pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        // Ensure the array is long enough to potentially have an out-of-bounds access
        vm.assume(_tos.length <= type(uint256).max);

        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool willRevert = false;
        for(uint i = 0; i <= _tos.length; i++) {
            (bool success, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[i % _tos.length], v));
            if(!success) {
                willRevert = true;
                break;
            }
        }

        // Call the actual contract function
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));

        // The correct contract should revert when there is an out-of-bounds access (i == _tos.length)
        // The buggy contract would not revert in that case
        // We assert that if the loop would revert at index == _tos.length, the contract call should revert
        // This is not directly testable because the contract's internal loop is not observable
        // Instead, we test that the contract call should revert for any input where the array length would cause out-of-bounds
        // However, this property is too complex. Let's use a simpler property:
        // The correct contract will revert when the loop index goes out of bounds, which happens for any valid input
        // because the bug is in the loop condition
        // Actually, the correct contract will never revert due to out-of-bounds because it stops at i < _tos.length
        // The buggy contract will revert when i == _tos.length because of the out-of-bounds access
        // So we can test: for any input, the correct contract should succeed (no revert)

        // This property is: the correct contract should never revert when _tos.length > 0
        assertTrue(success, "transfer should not revert when _tos.length > 0");
    }
}

